pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // 1. keep the fuzzed deposit amount in an admissible (wide) range:
        //    must be > 0 so it can be deposited, and small enough that the
        //    owner can afford to receive the transfer via transfer()'s 2300 gas
        amount = bound(amount, 1, 1e24);

        // 2. fund the test contract (the owner) and deposit into c via its
        //    payable fallback, so the contract holds exactly `amount`
        vm.deal(address(this), amount + 1);
        (bool depositOk, ) = address(c).call{value: amount}("");
        assertTrue(depositOk);
        assertEq(address(c).balance, amount);
        assertEq(c.depositsCount(), 1);
        uint256 ownerBefore = address(this).balance;

        // 3. drive c through withdrawAll (owner == this) and assert the
        //    general rule: the whole balance is withdrawn to the owner
        c.withdrawAll();

        assertTrue(
            address(c).balance == 0 && address(this).balance == ownerBefore + amount,
            "withdrawAll must drain the contract balance to the owner"
        );
    }

    // forge-std Test already declares payable receive/fallback; kept implicit.
}

