pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // Admissible domain: the contract holds a strictly positive balance.
        amount = bound(amount, 1 wei, type(uint128).max);
        vm.deal(address(c), amount);

        // Owner (the deployer, address(this)) drives c through withdrawAll.
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for any positive contract balance, the owner's
        // withdrawAll performs the full-balance transfer and therefore must
        // NOT complete successfully here (the owner rejects the ETH); the
        // mutant, having an empty body, completes successfully for the same
        // input — violating the rule.
        assertTrue(!ok, "withdrawAll must not succeed against a non-receiving owner");
    }
}

