pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0 && amount < type(uint128).max);
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));
        vm.assume(actor != tx.origin);

        // fund c through its payable fallback
        vm.deal(address(this), amount);
        (bool okFund, ) = address(c).call{value: amount}("");
        assertTrue(okFund);

        uint256 callerBefore = actor.balance;
        uint256 contractBefore = address(c).balance;
        assertTrue(contractBefore == amount);

        // non-owner attempts to drain the contract
        vm.prank(actor);
        try c.withdrawAll() {
            // reference C: unreachable for a non-owner
            assertTrue(actor.balance == callerBefore, "non-owner must not gain funds");
        } catch {
            // reference C: onlyOwner reverts, balances untouched
            assertTrue(actor.balance == callerBefore && address(c).balance == contractBefore, "revert leaves balances intact");
        }
    }
}

