    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 total, uint256 value) public {
        total = bound(total, 1, type(uint256).max / 2);
        value = bound(value, 0, total - 1); // strictly less than total

        // fund c through its payable fallback
        address funder = address(0xBEEF);
        vm.deal(funder, total);
        vm.prank(funder);
        (bool sent, ) = address(c).call{value: total}("");
        assertTrue(sent);

        // owner is the test contract (deployer), drive c through withdraw
        c.withdraw(value);

        // Rule: withdrawing value leaves total - value in the contract
        assertTrue(address(c).balance == total - value);
    }
}

